import * as z from "zod/v4";

test("x", () => {
  let n = 0;
  const s = z.object({
    a: z.string().default(() => {
      n++;
      if (n === 2) throw new Error("second call");
      return "d";
    }),
  });
  expect(s.parse({})).toEqual({ a: "d" });
  expect(n).toBe(1);
});

